const host = ref(null);
let controller = null;

onMounted(() => {
  controller = bindLinearScene(host.value, { interactive: props.interactive });
  if (props.replay) controller.replay();
});

watch(
  () => props.replay,
  () => controller?.replay(),
);

onBeforeUnmount(() => controller?.destroy());
